SELECT EXISTS(
    SELECT 1
    FROM tbl_dim_project
    WHERE customer_id = #{customerId}
      AND delete_flag = FALSE
      AND deleted_at IS NULL
      AND status = 'ACTIVE'
      AND LOWER(BTRIM(project_alias)) = LOWER(BTRIM(#{projectAlias}))

          AND project_id <> #{excludeProjectId}

)

mapper.update:
UPDATE tbl_project_team
SET status = 'DELETED',
    deleted_at = #{deletedAt},
    deleted_by = #{deletedBy},
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
WHERE project_id = #{projectId}
  AND team_id = #{teamId}
  AND deleted_at IS NULL
  AND status = 'ACTIVE'

UPDATE tbl_project_team
SET status = 'ACTIVE',
    deleted_at = NULL,
    deleted_by = NULL,
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
WHERE project_id = #{projectId}
  AND team_id = #{teamId}
  AND (deleted_at IS NOT NULL OR status = 'DELETED')
